import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameter: the candidate new owner address
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid the zero address triviality where both implementations coincide
        // (the property still must hold for all inputs on the reference, but the mutant only differs when newOwner != address(0))
        vm.assume(newOwner != address(0));

        // The test runs as the current owner. In the reference contract owner is uninitialized (zero) so
        // transferOwnership is protected by onlyOwner; to call transferOwnership we must be the owner.
