pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: currentOwner (as an address to act from) and newOwner (the address passed to transferOwnership)
    function testFuzz_property(address currentOwner, address newOwner) public {
        // Keep addresses wide but non-zero for clarity; allow zero as admissible as well
        vm.assume(currentOwner != address(0) || currentOwner == address(0));
        vm.assume(newOwner != address(0) || newOwner == address(0));

        // Initialize contract owner to currentOwner by performing a prank from currentOwner and directly setting owner
        // The contract's owner is public but not settable except via transferOwnership which is onlyOwner; since on deployment owner is address(0), we set up by impersonating address(0) to call transferOwnership to currentOwner if needed.
        // Step 1: if currentOwner is address(0), owner already is address(0) after deploy; otherwise, we need to make address(0) the caller to set owner to currentOwner.

        if (currentOwner != address(0)) {
            // From deploy, owner == address(0). Have address(0) call transferOwnership(currentOwner)
            vm.prank(address(0));
            c.transferOwnership(currentOwner);
        }

        // At this point, the contract's owner() should equal currentOwner.
        address before = c.owner();
        // sanity: before equals currentOwner
        // Now attempt to call transferOwnership(newOwner) as currentOwner and observe behavior
        bool ok;
        vm.prank(currentOwner);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: when the legitimate owner (currentOwner) calls transferOwnership, the call should succeed and update owner to newOwner.
        // For the reference contract: if msg.sender == owner, transferOwnership should succeed and owner()==newOwner.
        // The mutant inverts the require, so when the legitimate owner calls it the mutant will revert, preserving old owner; thus the property distinguishes them.
        // Assert the property: if the owner call succeeded (ok==true), then the contract's owner getter must equal newOwner. If the call failed (ok==false), then owner must still equal before.
        // This single assertTrue encodes the invariant on observable behavior for all inputs for the reference, and is violated by the mutant for some inputs.

        address after = c.owner();
        // Form the condition that always holds for the correct contract: ok implies after==newOwner; !ok implies after==before.
        bool cond = (ok && after == newOwner) || (!ok && after == before);
        assertTrue(cond);
    }
}

